<?php
require __DIR__.'/../app/bootstrap.php'; require_role(['admin','collector','expert']);
require_once __DIR__.'/../app/Services/CsvImporter.php';
$importer=new CsvImporter(); $data=$_SESSION['_asset_import']??[]; unset($_SESSION['_asset_import']); $error=null;
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['upload_csv'])){
    verify_csrf();
    if(empty($_FILES['csv']['tmp_name']) || $_FILES['csv']['error']!==UPLOAD_ERR_OK) $error='فایل CSV انتخاب نشده یا قابل دریافت نیست.';
    else { $ext=strtolower(pathinfo($_FILES['csv']['name'],PATHINFO_EXTENSION)); $max=(int)app_config()['security']['upload_max_mb']*1024*1024;
      if($ext!=='csv' || (int)$_FILES['csv']['size']>$max) $error='فقط فایل CSV تا حجم مجاز قابل بارگذاری است.';
      else { try { $rows=$importer->rows($_FILES['csv']['tmp_name']); $row=$rows->current(); if(!$row) throw new RuntimeException('فایل داده‌ای ندارد.'); $data=$row; $data['_source_file']=basename($_FILES['csv']['name']); $_SESSION['_asset_import']=$data; audit('hardware_csv_preview','asset',null,['file'=>$data['_source_file']]); } catch(Throwable $e){$error=$e->getMessage();} }
    }
}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_asset'])){
 verify_csrf(); $assetNo=trim((string)($_POST['asset_no']??''));
 if(!preg_match('/^\d{7}$/',$assetNo)) $error='شماره اموال باید دقیقاً ۷ رقم باشد.';
 else { $check=db()->prepare('SELECT asset_no FROM assets WHERE asset_no=?');$check->execute([$assetNo]); if($check->fetchColumn()){ flash('warning','شماره اموال تکراری است؛ ویرایش مورد موجود را انجام دهید.'); header('Location: '.url('asset_view.php?asset_no='.urlencode($assetNo).'&edit=1')); exit; }
   $technical=$_POST['technical']??[]; $technical=array_map('trim',$technical); $source=(string)($_POST['_source_file']??'');
   $st=db()->prepare('INSERT INTO assets(asset_no,asset_type,device_subtype,hostname,personnel_id,location,department,manufacturer,model,serial_no,technical,status,source_file,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
   $st->execute([$assetNo,$_POST['asset_type']??'computer',trim((string)($_POST['device_subtype']??'')),trim((string)($_POST['hostname']??''),),($_POST['personnel_id']??'')!==''?(int)$_POST['personnel_id']:null,trim((string)($_POST['location']??'')),trim((string)($_POST['department']??'')),trim((string)($_POST['manufacturer']??'')),trim((string)($_POST['model']??'')),trim((string)($_POST['serial_no']??'')),json_encode($technical,JSON_UNESCAPED_UNICODE),$_POST['status']??'active',$source,user()['id'],user()['id']]);
   $disks=$importer->disks($data); foreach($disks as $d){$q=db()->prepare('INSERT INTO asset_disks(asset_no,disk_index,model,size_gb,serial_no,interface_name,media) VALUES(?,?,?,?,?,?,?)');$q->execute([$assetNo,$d['index'],$d['model'],$d['size_gb'],$d['serial_no'],$d['interface']??null,$d['media']??null]);}
   $rams=$importer->ramSlots($data); foreach($rams as $r){$q=db()->prepare('INSERT INTO asset_ram_slots(asset_no,slot_no,state,capacity_gb,ram_type,speed_mhz,manufacturer,part_number,serial_no) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$assetNo,$r['slot_no'],$r['state']??'unknown',$r['capacity_gb']??null,$r['ram_type']??null,$r['speed_mhz']??null,$r['manufacturer']??null,$r['part_number']??null,$r['serial_no']??null]);}
   audit('asset_created','asset',$assetNo,['type'=>$_POST['asset_type']??'computer','source'=>$source]); flash('success','تجهیز با موفقیت ثبت شد.'); redirect('asset_view.php?asset_no='.urlencode($assetNo));
 }
}
$people=db()->query('SELECT id,full_name,personnel_code,department FROM personnel ORDER BY full_name LIMIT 5000')->fetchAll();
$val=fn($key,$default='')=>$_POST[$key]??$data[$key]??$default;
$technicalKeys=['SystemType'=>'نوع سیستم','OSName'=>'سیستم‌عامل','OSVersion'=>'نسخه سیستم‌عامل','CPUName'=>'پردازنده','GPUDetails'=>'پردازنده گرافیکی','RAMTotalGB'=>'RAM کل (GB)','RAMSlotCount'=>'تعداد اسلات RAM','MotherboardManufacturer'=>'سازنده مادربرد','MotherboardProduct'=>'مدل مادربرد','MotherboardSerial'=>'سریال مادربرد','IPAddresses'=>'IP','MACAddresses'=>'MAC','Domain'=>'دامنه','AntivirusDetails'=>'آنتی‌ویروس','NetworkDetails'=>'اطلاعات شبکه','DiskDetails'=>'اطلاعات دیسک'];
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ثبت مورد جدید</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="assets.php">تجهیزات</a><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><h1>ثبت مورد جدید</h1><p class="muted">ابتدا CSV را بارگذاری کنید؛ سپس مقادیر استخراج‌شده را بررسی و تکمیل کنید.</p></div></div><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><section class="panel"><h2>۱. بارگذاری خروجی پایش</h2><form method="post" enctype="multipart/form-data" class="upload-row"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="file" name="csv" accept=".csv,text/csv" required><button class="btn" name="upload_csv" value="1">تحلیل CSV</button></form></section><form method="post" class="panel"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="save_asset" value="1"><input type="hidden" name="_source_file" value="<?=e($val('_source_file'))?>"><h2>۲. مشخصات ثبت</h2><div class="form-grid"><label>شماره اموال *<input name="asset_no" value="<?=e($val('asset_no'))?>" inputmode="numeric" pattern="\d{7}" maxlength="7" required></label><label>نوع دستگاه<select name="asset_type"><option value="computer">رایانه</option><option value="printer">چاپگر</option><option value="display">نمایشگر</option><option value="scanner">اسکنر</option></select></label><label>زیرنوع دستگاه<input name="device_subtype" value="<?=e($val('device_subtype'))?>"></label><label>نام دستگاه / Hostname<input name="hostname" value="<?=e($val('ComputerName'))?>"></label><label>کاربر اصلی / مسئول<select name="personnel_id"><option value="">انتخاب پرسنل</option><?php foreach($people as $p):?><option value="<?=$p['id']?>" <?=((string)($val('personnel_id'))===(string)$p['id'])?'selected':''?>><?=e($p['full_name'].' — '.($p['personnel_code']??''))?></option><?php endforeach;?></select></label><label>مکان<input name="location" value="<?=e($val('location'))?>"></label><label>دانشکده / اداره / گروه<input name="department" value="<?=e($val('department'))?>"></label><label>برند<input name="manufacturer" value="<?=e($val('Manufacturer'))?>"></label><label>مدل<input name="model" value="<?=e($val('Model'))?>"></label><label>شماره سریال<input name="serial_no" value="<?=e($val('SystemSerial'))?>"></label><label>وضعیت<select name="status"><option value="active">فعال</option><option value="repair">تعمیر</option><option value="retired">اسقاط</option><option value="lost">مفقود</option></select></label></div><h2>۳. اطلاعات فنی استخراج‌شده</h2><div class="form-grid"><?php foreach($technicalKeys as $k=>$label):?><label><?=$label?><textarea name="technical[<?=e($k)?>]" rows="2"><?=e($val($k))?></textarea></label><?php endforeach;?></div><div class="actions"><button class="btn primary" type="submit">ذخیره نهایی</button><a class="btn" href="assets.php">انصراف</a></div></form></main></body></html>
